actions.script:
const number = (value) => value == null || value === '' ? null : Number(value)
const out = ec.service.sync().name('org.moqui.edge.ClientSyncServices.upload#Chunk').parameters({uploadId: uploadId || '',
    offset: number(offset), total: number(total), fileName: fileName || null, contentType: contentType || null, chunk: chunk || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {uploadId: out.uploadId, received: out.received, total: out.total,
    accepted: out.accepted === true, complete: out.complete === true})

const out = ec.service.sync().name('org.moqui.edge.ClientSyncServices.get#UploadStatus').parameter('uploadId', uploadId || '').call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {found: out.found === true, received: out.received, total: out.total,
    complete: out.complete === true, fileName: out.fileName})
